### Create custom HttpExceptionFilter with @Catch

Source: https://github.com/nestjs/docs.nestjs.com/blob/master/content/exception-filters.md

Implement an exception filter for HttpException instances to access platform Request and Response objects and return a customized response payload. When using Fastify, replace response.json() with response.send().

```typescript
@@filename(http-exception.filter)
import { ExceptionFilter, Catch, ArgumentsHost, HttpException } from '@nestjs/common';
import { Request, Response } from 'express';

@Catch(HttpException)
export class HttpExceptionFilter implements ExceptionFilter {
  catch(exception: HttpException, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const request = ctx.getRequest<Request>();
    const status = exception.getStatus();

    response
      .status(status)
      .json({
        statusCode: status,
        timestamp: new Date().toISOString(),
        path: request.url,
      });
  }
}
@@switch
